SourceCode.Declaration:
/// <summary>
/// Controller class for the SysOperation framework batch job
/// that updates pallet-related quantities (CartonPerPallet,
/// PalletLayerQty, PalletQty) in Default Order Settings.
/// </summary>
class METInventItemOrderSetupUpdatePalletQuantitiesController extends SysOperationServiceController
{

}

Method.Source:
/// <summary>
/// Initializes the controller by binding it to the pallet quantities service and process method.
/// </summary>
protected void new()
{
    super(classstr(METInventItemOrderSetupUpdatePalletQuantitiesService), methodstr(METInventItemOrderSetupUpdatePalletQuantitiesService, process), SysOperationExecutionMode::Synchronous);
}

// <summary>
/// Provides the default caption for the batch job.
/// This caption will be displayed in the batch job dialog.
/// </summary>
/// <returns>
/// Localized label string for the batch job caption.
/// </returns>
protected ClassDescription defaultCaption()
{
    return "@MET:UpdatePalletQty";
}

/// <summary>
/// Main entry point for the controller.
/// Initializes the SysOperation framework and starts the batch job
/// for updating pallet-related quantities in Default Order Settings.
/// </summary>
/// <param name="_args">
/// Arguments passed from the menu item or job execution.
/// </param>
/// <remarks>
/// This method ties together the contract, service, and controller.
/// It ensures the batch job runs correctly when triggered.
/// </remarks>
public static void main(Args _args)
{
    METInventItemOrderSetupUpdatePalletQuantitiesController controller = new METInventItemOrderSetupUpdatePalletQuantitiesController();

    controller.parmArgs(_args);
    controller.startOperation();
}
